/* Model-free, packing/pool-inclusive correctness and component timing. */
#define _GNU_SOURCE
#include <math.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#ifdef _WIN32
#include <windows.h>
#endif
#include "common/sysinfo.h"
#include "llm/matvec.h"
#ifdef PANEL_API
#include "llm/quant_panel.h"
#define BENCH_GROUP(pool, tasks, n) \
    janas_matvec_q4k_group_stats(pool, tasks, n, &stats)
#else
#define BENCH_GROUP(pool, tasks, n) janas_matvec_q4k_group(pool, tasks, n)
#endif

enum { N_SAMPLES = 7 };
static uint32_t rng = 7;

static uint32_t rnd(void)
{
    rng = rng * 1664525u + 1013904223u;
    return rng;
}

static double now(void)
{
#ifdef _WIN32
    LARGE_INTEGER count, frequency;
    QueryPerformanceCounter(&count);
    QueryPerformanceFrequency(&frequency);
    return (double)count.QuadPart / (double)frequency.QuadPart;
#else
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return (double)t.tv_sec + (double)t.tv_nsec * 1e-9;
#endif
}

static int exact(int type, const unsigned char *w, size_t row_bytes,
                 const uint8_t *p1, const uint8_t *p0,
                 const struct janas_block_q8k *x, const float *y,
                 size_t matrices, size_t rows, size_t nv, size_t nb)
{
    for (size_t i = 0; i < matrices; i++)
        for (size_t v = 0; v < nv; v++)
            for (size_t r = 0; r < rows; r++) {
                const void *row = w + (i * rows + r) * row_bytes;
                float reference = type == JANAS_Q4_K
                    ? janas_q4k_dot_ref(row, x + v * nb, nb)
                    : type == JANAS_Q6_K
                    ? janas_q6k_dot_ref(row, x + v * nb, nb)
                    : janas_q6kp_dot_ref(row, p1 + r * nb * 64,
                                         p0 + r * nb * 64, x + v * nb, nb);
                if (memcmp(&reference, y + (i * nv + v) * rows + r,
                           sizeof reference)) {
                    fprintf(stderr, "exact comparison failed at %zu/%zu/%zu\n", i, v, r);
                    return 0;
                }
            }
    return 1;
}

int main(int argc, char **argv)
{
    int type = argc > 1 ? atoi(argv[1]) : JANAS_Q4_K;
    size_t cols = argc > 2 ? (size_t)atoi(argv[2]) : 2048;
    size_t rows = argc > 3 ? (size_t)atoi(argv[3]) : 512;
    size_t nv = argc > 4 ? (size_t)atoi(argv[4]) : 5;
    int threads = argc > 5 ? atoi(argv[5]) : 8;
    if ((type != JANAS_Q4_K && type != JANAS_Q6_K && type != JANAS_Q6_K_P) ||
        !cols || cols % 256 || !rows || !nv || nv > 9 || threads < 1 || threads > 8)
        return 2;
    size_t nb = cols / 256, row_bytes = janas_qtype_row_bytes(type, cols);
    size_t matrices = type == JANAS_Q4_K && rows == 512 && cols == 2048 ? 2 : 1;
    if (!row_bytes || rows > SIZE_MAX / matrices / row_bytes ||
        rows > SIZE_MAX / nb / sizeof(struct janas_block_q6k) ||
        nv > SIZE_MAX / nb / sizeof(struct janas_block_q8k) ||
        cols > SIZE_MAX / sizeof(float) || rows > SIZE_MAX / matrices / nv / sizeof(float))
        return 2;
    unsigned char *w = malloc(matrices * rows * row_bytes);
    uint8_t *p1 = malloc(rows * nb * 64), *p0 = malloc(rows * nb * 64);
    struct janas_block_q8k *x = malloc(nv * nb * sizeof(*x));
    float *xf = malloc(cols * sizeof(*xf));
    float *y = malloc(matrices * rows * nv * sizeof(*y));
    struct janas_block_q6k *raw = malloc(rows * nb * sizeof(*raw));
    if (!w || !p1 || !p0 || !x || !xf || !y || !raw)
        return 2;
    for (size_t i = 0; i < matrices * rows * row_bytes; i++)
        w[i] = (uint8_t)(rnd() >> 24);
    if (type == JANAS_Q4_K) {
        struct janas_block_q4k *blocks = (void *)w;
        for (size_t i = 0; i < matrices * rows * nb; i++) {
            blocks[i].d = janas_fp32_to_fp16(.001f);
            blocks[i].dmin = janas_fp32_to_fp16(.0005f);
        }
    } else if (type == JANAS_Q6_K) {
        for (size_t i = 0; i < rows * nb; i++)
            ((struct janas_block_q6k *)w)[i].d = janas_fp32_to_fp16(.001f);
    } else {
        for (size_t i = 0; i < rows * nb * sizeof(*raw); i++)
            ((uint8_t *)raw)[i] = (uint8_t)(rnd() >> 24);
        for (size_t i = 0; i < rows * nb; i++)
            raw[i].d = janas_fp32_to_fp16(.001f);
        janas_q6k_to_planes(raw, rows * nb, (void *)w, p1, p0);
    }
    for (size_t v = 0; v < nv; v++) {
        for (size_t i = 0; i < cols; i++)
            xf[i] = (float)(rnd() >> 8) / 8388608.0f - 1;
        janas_q8k_quantize(xf, x + v * nb, cols);
    }
    struct janas_cpu_layout layout;
    if (janas_cpu_layout(NULL, 0, &layout) || threads > layout.n)
        return 2;
    struct janas_pool *pool = janas_pool_create(threads, layout.cpus);
    if (!pool)
        return 2;
    janas_pin_current_thread(layout.cpus[0]);
    struct janas_matvec_task tasks[2];
    for (size_t i = 0; i < matrices; i++)
        tasks[i] = (struct janas_matvec_task){
            .type = type, .w = w + i * rows * row_bytes,
            .plane = {type == JANAS_Q6_K_P ? p1 : NULL,
                      type == JANAS_Q6_K_P ? p0 : NULL},
            .x = x, .y = y + i * rows * nv, .rows = rows, .cols = cols, .n_vec = nv};
#ifdef PANEL_API
    struct janas_matvec_stats stats;
#endif
    BENCH_GROUP(pool, tasks, matrices);
    if (!exact(type, w, row_bytes, p1, p0, x, y, matrices, rows, nv, nb))
        return 1;

    /* Warm actively, including the same allocation, packing and pool work. */
    double begin = now(), warmup_elapsed;
    size_t warmup_iterations = 0;
    do {
        BENCH_GROUP(pool, tasks, matrices);
        warmup_iterations++;
        warmup_elapsed = now() - begin;
    } while (warmup_elapsed < .5);

    double elapsed[N_SAMPLES], seconds[N_SAMPLES];
    size_t iterations[N_SAMPLES], count = 1;
    for (int sample = 0; sample < N_SAMPLES; sample++) {
        for (;;) {
            begin = now();
            for (size_t i = 0; i < count; i++)
                BENCH_GROUP(pool, tasks, matrices);
            elapsed[sample] = now() - begin;
            if (elapsed[sample] >= .1)
                break;
            if (count > SIZE_MAX / 2)
                return 2;
            count *= 2;
        }
        iterations[sample] = count;
        seconds[sample] = elapsed[sample] / (double)count;
        if (!isfinite(seconds[sample]) || seconds[sample] <= 0)
            return 2;
    }
    if (!exact(type, w, row_bytes, p1, p0, x, y, matrices, rows, nv, nb))
        return 1;
    int panels_enabled = 0, counters_available = 0;
    uint64_t prepared_rows = 0, prepared_vectors = 0, established_rows = 0;
    uint64_t established_vectors = 0, panel_views = 0, panel_unique = 0;
    uint64_t panel_dedup_hits = 0, panel_bytes = 0;
    double panel_prepare_seconds = 0;
#ifdef PANEL_API
    panels_enabled = janas_quant_panels_enabled();
    counters_available = 1;
    prepared_rows = stats.prepared_rows;
    prepared_vectors = stats.prepared_row_vectors;
    established_rows = stats.established_rows;
    established_vectors = stats.established_row_vectors;
    panel_views = stats.panel_views;
    panel_unique = stats.panel_unique;
    panel_dedup_hits = stats.panel_dedup_hits;
    panel_bytes = stats.panel_bytes;
    panel_prepare_seconds = stats.panel_prepare_seconds;
#endif
    printf("{\"schema\":1,\"type\":%d,\"cols\":%zu,\"rows\":%zu,\"nv\":%zu,"
           "\"threads\":%d,\"matrices\":%zu,\"exact\":true,"
           "\"warmup_elapsed_seconds\":%.17g,\"warmup_iterations\":%zu,"
           "\"panels_enabled\":%d,\"dispatch_counters_available\":%d,"
           "\"dispatch_counter_scope\":\"final_completed_group\","
           "\"actual_prepared_rows\":%llu,\"actual_prepared_row_vectors\":%llu,"
           "\"established_rows\":%llu,\"established_row_vectors\":%llu,"
           "\"panel_views\":%llu,\"panel_unique\":%llu,\"panel_dedup_hits\":%llu,"
           "\"panel_bytes\":%llu,\"panel_prepare_seconds\":%.17g,\"samples_seconds\":[",
           type, cols, rows, nv, threads, matrices, warmup_elapsed, warmup_iterations,
           panels_enabled, counters_available, (unsigned long long)prepared_rows,
           (unsigned long long)prepared_vectors, (unsigned long long)established_rows,
           (unsigned long long)established_vectors, (unsigned long long)panel_views,
           (unsigned long long)panel_unique, (unsigned long long)panel_dedup_hits,
           (unsigned long long)panel_bytes, panel_prepare_seconds);
    for (int i = 0; i < N_SAMPLES; i++)
        printf("%s%.17g", i ? "," : "", seconds[i]);
    printf("],\"sample_elapsed_seconds\":[");
    for (int i = 0; i < N_SAMPLES; i++)
        printf("%s%.17g", i ? "," : "", elapsed[i]);
    printf("],\"sample_iterations\":[");
    for (int i = 0; i < N_SAMPLES; i++)
        printf("%s%zu", i ? "," : "", iterations[i]);
    puts("]}");
    janas_pool_destroy(pool);
    free(w); free(p1); free(p0); free(x); free(xf); free(y); free(raw);
    return 0;
}

