float janas_fp16_to_fp32(uint16_t h)
{
    uint32_t sign = (uint32_t)(h & 0x8000) << 16;
    uint32_t exp = (h >> 10) & 0x1f;
    uint32_t mant = h & 0x3ff;
    uint32_t bits;

    if (exp == 0) {
        if (mant == 0) {
            bits = sign;
        } else { /* subnormal: normalise */
            exp = 127 - 15 + 1;
            while (!(mant & 0x400)) {
                mant <<= 1;
                exp--;
            }
            bits = sign | (exp << 23) | ((mant & 0x3ff) << 13);
        }
    } else if (exp == 0x1f) {
        bits = sign | 0x7f800000 | (mant << 13);
    } else {
        bits = sign | ((exp + 127 - 15) << 23) | (mant << 13);
    }
    float f;
    memcpy(&f, &bits, sizeof(f));
    return f;
}

uint16_t janas_fp32_to_fp16(float f)
{
    uint32_t x;
    memcpy(&x, &f, sizeof(x));
    uint32_t sign = (x >> 16) & 0x8000;
    int32_t exp = (int32_t)((x >> 23) & 0xff) - 127 + 15;
    uint32_t mant = x & 0x7fffff;

    if (((x >> 23) & 0xff) == 0xff) /* inf or nan */
        return (uint16_t)(sign | 0x7c00 | (mant ? 0x200 : 0));
    if (exp >= 0x1f)
        return (uint16_t)(sign | 0x7c00);
    if (exp <= 0) {
        if (exp < -10)
            return (uint16_t)sign;
        mant |= 0x800000;
        uint32_t shift = (uint32_t)(14 - exp);
        uint32_t half = mant >> shift;
        uint32_t rem = mant & ((1u << shift) - 1);
        uint32_t mid = 1u << (shift - 1);
        if (rem > mid || (rem == mid && (half & 1)))
            half++;
        return (uint16_t)(sign | half);
    }
    uint32_t half = sign | ((uint32_t)exp << 10) | (mant >> 13);
    uint32_t rem = mant & 0x1fff;
    if (rem > 0x1000 || (rem == 0x1000 && (half & 1)))
        half++; /* may carry into the exponent, which is correct rounding */
    return (uint16_t)half;
}

const int8_t janas_mxfp4_values[16] = {0, 1,  2,  3,  4,  6,  8,  12,
                                       0, -1, -2, -3, -4, -6, -8, -12};

float janas_e8m0_half(uint8_t e)
{
    uint32_t bits = e < 2 ? 0x00200000u << e : (uint32_t)(e - 1) << 23;
    float f;
    memcpy(&f, &bits, sizeof(f));
    return f;
}

static float ue4m3_value(uint8_t x)
{
    if (x == 0 || x == 0x7F)
        return 0.0f;
    int e = (x >> 3) & 15, man = x & 7;
    float raw = e == 0 ? ldexpf((float)man, -9)
                       : ldexpf(1.0f + (float)man / 8.0f, e - 7);
    return raw * 0.5f;
}

/* all 256 bytes' values, made once */
static float ue4m3_tab[256];
static pthread_once_t ue4m3_once = PTHREAD_ONCE_INIT;
static void ue4m3_init(void)
{
    for (int i = 0; i < 256; i++)
        ue4m3_tab[i] = ue4m3_value((uint8_t)i);
}

float janas_ue4m3_half(uint8_t x)
{
    pthread_once(&ue4m3_once, ue4m3_init);
    return ue4m3_tab[x];
}

int janas_mxfp4_to_q8_0(const uint8_t *in, struct janas_block_q8_0 *out,
                        size_t n, size_t *tiny)
{
    const int8_t *kv = janas_mxfp4_values;
    for (size_t b = 0; b < n; b++) {
        const uint8_t *x = in + b * JANAS_MXFP4_BLOCK;
        int p = (int)x[0] - 128; /* the block's power of two */
        if (x[0] == 0xFF || p > 15)
            return -1;
        /* fp16 of 2^p: normal from 2^-14, subnormal down to 2^-24 */
        uint16_t d = p >= -14   ? (uint16_t)((p + 15) << 10)
                     : p >= -24 ? (uint16_t)(1u << (p + 24))
                                : 0;
        if (!d)
            ++*tiny;
        out[b].d = d;
        for (int j = 0; j < 16; j++) {
            out[b].qs[j] = d ? kv[x[1 + j] & 15] : 0;
            out[b].qs[j + 16] = d ? kv[x[1 + j] >> 4] : 0;
        }
    }
    return 0;
}

