/* JANAS_KERNELS=ref, read once in dot_kernels_init (janas_kernels_ref). */
static int kernels_ref;

/* Resolved before main: the kernels are first called from pool threads. */
__attribute__((constructor)) static void dot_kernels_init(void)
{
    /* NVFP4's scales, before any kernel reads them (not once a row) */
    pthread_once(&ue4m3_once, ue4m3_init);
#if defined(__x86_64__)
    for (int e = 0; e < 256; e++)
        e8m0_tab[e] = janas_e8m0_half((uint8_t)e);
    for (uint32_t i = 0; i < 256; i++) {
        uint64_t m = 0;
        for (int j = 0; j < 8; j++)
            m |= (uint64_t)(i >> j & 1 ? 0xff : 0x01) << 8 * j;
        iq_byte64[i] = m;
    }
    for (uint32_t i = 0; i < 128; i++)
        iq_sign64[i] = iq_byte64[iq_signs(i)];
    __builtin_cpu_init();
    if (__builtin_cpu_supports("avx2") && __builtin_cpu_supports("fma") &&
        __builtin_cpu_supports("f16c")) {
        dot_impl = q4k_dot_avx2;
        dot6_impl = q6k_dot_avx2;
        dot5_impl = q5k_dot_avx2;
        dot80_impl = q8_0_dot_avx2;
        dotnl_impl = iq4nl_dot_avx2;
        dotmx_impl = mxfp4_dot_avx2;
        dotxs_impl = iq4xs_dot_avx2;
        dot40_impl = q4_0_dot_avx2;
        dot51_impl = q5_1_dot_avx2;
        dot41_impl = q4_1_dot_avx2;
        dot50_impl = q5_0_dot_avx2;
        dotx3_impl = iq3xxs_dot_avx2;
        dotx2_impl = iq2_dot_avx2;
        dotx1_impl = iq1m_dot_avx2;
        dotx1s_impl = iq1s_dot_avx2;
        dot2k_impl = q2k_dot_avx2;
        dot20_impl = q2_0_dot_avx2;
        dot3_impl = q3k_dot_avx2;
        dotis_impl = iq3s_dot_avx2;
        dot6p_impl = q6kp_dotn_avx2;
        dot_name = "avx2";
        const char *qg = getenv("JANAS_CPU_TILES");
        use_tiles = !(qg && atoi(qg) == 0);
        const char *k = getenv("JANAS_KERNELS"); /* avx2: no VNNI */
        int plain = k && !strcmp(k, "avx2");
        /* 256: the tiles on 256 bits even where 512 are there */
        int z = !plain && !(k && !strcmp(k, "256")) &&
                __builtin_cpu_supports("avx512f") &&
                __builtin_cpu_supports("avx512bw") &&
                __builtin_cpu_supports("avx512vl") &&
                __builtin_cpu_supports("avx512vnni");
        if (__builtin_cpu_supports("avxvnni") && !plain) {
            use_vnni = 1;
            dot_impl = q4k_dot_vnni;
            dot6_impl = q6k_dot_vnni;
            dot5_impl = q5k_dot_vnni;
            dot80_impl = q8_0_dot_vnni;
            dotnl_impl = iq4nl_dot_vnni;
            dotmx_impl = mxfp4_dot_vnni;
            dotxs_impl = iq4xs_dot_vnni;
            dot40_impl = q4_0_dot_vnni;
            dot51_impl = q5_1_dot_vnni;
            dot41_impl = q4_1_dot_vnni;
            dot50_impl = q5_0_dot_vnni;
            dotx3_impl = iq3xxs_dot_vnni;
            dotx2_impl = iq2_dot_vnni;
            dotx1_impl = iq1m_dot_vnni;
            dotx1s_impl = iq1s_dot_vnni;
            dot2k_impl = q2k_dot_vnni;
            dot20_impl = q2_0_dot_vnni;
            dot3_impl = q3k_dot_vnni;
            dotis_impl = iq3s_dot_vnni;
            dot6p_impl = q6kp_dotn_vnni;
            dot_name = z ? "avx-vnni (512-bit tiles)" : "avx-vnni";
        } else if (__builtin_cpu_supports("avx512vnni") &&
                   __builtin_cpu_supports("avx512vl") && !plain) {
            use_vnni = use_evnni = 1;
            dot_impl = q4k_dot_evnni;
            dot6_impl = q6k_dot_evnni;
            dot5_impl = q5k_dot_evnni;
            dot80_impl = q8_0_dot_evnni;
            dotnl_impl = iq4nl_dot_evnni;
            dotmx_impl = mxfp4_dot_evnni;
            dotxs_impl = iq4xs_dot_evnni;
            dot40_impl = q4_0_dot_evnni;
            dot51_impl = q5_1_dot_evnni;
            dot41_impl = q4_1_dot_evnni;
            dot50_impl = q5_0_dot_evnni;
            dotx3_impl = iq3xxs_dot_evnni;
            dotx2_impl = iq2_dot_evnni;
            dotx1_impl = iq1m_dot_evnni;
            dotx1s_impl = iq1s_dot_evnni;
            dot2k_impl = q2k_dot_evnni;
            dot20_impl = q2_0_dot_evnni;
            dot3_impl = q3k_dot_evnni;
            dotis_impl = iq3s_dot_evnni;
            dot6p_impl = q6kp_dotn_evnni;
            dot_name = z ? "avx512-vnni (512-bit tiles)" : "avx512-vnni";
        } else if (plain && (__builtin_cpu_supports("avxvnni") ||
                             (__builtin_cpu_supports("avx512vnni") &&
                              __builtin_cpu_supports("avx512vl")))) {
            dot_name = "avx2 (VNNI left out: JANAS_KERNELS=avx2)";
        }
        use_z = z && use_vnni;
    }
#elif defined(__aarch64__)
    const char *k = getenv("JANAS_KERNELS"); /* ref: the scalar reference */
    kernels_ref = k && !strcmp(k, "ref");
    if (janas_cpu_arm_dotprod() && !kernels_ref) {
