size_t janas_q6k_tile_rows(int type, const void *w, size_t row_bytes,
                           const uint8_t *p1, const uint8_t *p0, size_t pb,
                           const struct janas_block_q8k *x, size_t x_stride,
                           size_t nv, size_t nb, size_t rows, float *y,
                           size_t y_stride)
{
#if defined(__x86_64__)
    size_t r8 = rows / 8 * 8;
    if (!use_tiles || !dot6p_impl ||
        nv < (type == JANAS_Q3_K ? TILES_MIN_NV_Q3K : TILES_MIN_NV) || !r8 ||
        (type != JANAS_Q6_K && type != JANAS_Q6_K_P && type != JANAS_Q3_K))
        return 0;
    /* q6k_gemm's L: 0 Q6_K, 1-3 Q6_K_P's level, 4 Q3_K */
    int level = type == JANAS_Q6_K   ? 0
                : type == JANAS_Q3_K ? 4
                : p0                 ? 3
                : p1                 ? 2
                                     : 1;
    size_t r16 = use_z ? r8 / 16 * 16 : 0;
    if (r16)
        q6k_gemm_z(w, row_bytes, p1, p0, pb, x, x_stride, nv, nb, r16, y,
                   y_stride, level);
    if (r8 > r16)
        (KPICK(q6k_gemm))((const char *)w + r16 * row_bytes, row_bytes,
                          p1 ? p1 + r16 * pb : NULL, p0 ? p0 + r16 * pb : NULL,
                          pb, x, x_stride, nv, nb, r8 - r16, y + r16, y_stride,
                          level);
    return r8;
#elif defined(__aarch64__)
    size_t r2 = rows / 2 * 2;
    if (!use_i8mm || type != JANAS_Q6_K_P || nv < 2 || !r2)
        return 0;
    /* Native Windows microbenchmarks establish gains for the 80B model's
       full six-bit, 512-column down products at four and eight vectors.
       Odd counts, other widths and lower prefixes keep the established
       rows unless JANAS_CPU_TILES=1 explicitly requests experimental tiles.
       In particular a two-vector tile plus a one-vector tail can lose to
       the existing three-vector kernel, which unpacks the weights once. */
    if (use_i8mm == 1 && (!p0 || nb != 2 || (nv != 4 && nv != 8)))
        return 0;
    q6kp_rows_i8mm(w, row_bytes, p1, p0, pb, x, x_stride, nv, nb, r2, y,
                    y_stride);
    return r2;
#else
    (void)type, (void)w, (void)row_bytes, (void)p1, (void)p0, (void)pb;
    (void)x, (void)x_stride, (void)nv, (void)nb, (void)rows, (void)y;
    (void)y_stride;
    return 0;
#endif
}

void janas_q6kp_dot_multi(const struct janas_block_q6kp *w, const uint8_t *p1,
                          const uint8_t *p0, const struct janas_block_q8k *x,
                          size_t x_stride, size_t nv, size_t nb, float *out,
                          size_t out_stride)
{
    size_t v = 0;
    if (dot6p_impl) {
        float r[8];
        int g = 1;
        for (; v < nv; v += (size_t)g) {
            g = nv - v >= 8 ? 8 : (int)(nv - v);
            dot6p_impl(w, p1, p0, x + v * x_stride, x_stride, g, nb, r);
            for (int i = 0; i < g; i++)
                out[(v + (size_t)i) * out_stride] = r[i];
        }
        return;
    }
    for (; v < nv; v++)
        out[v * out_stride] =
            janas_q6kp_dot_ref(w, p1, p0, x + v * x_stride, nb);
}

