static float dot_f32_ref(const float *a, const float *b, size_t n)
{
    float s = 0.0f;
    for (size_t i = 0; i < n; i++)
        s += a[i] * b[i];
    return s;
}

static void axpy_f32_ref(float *y, float a, const float *x, size_t n)
{
    for (size_t i = 0; i < n; i++)
        y[i] += a * x[i];
}

#if defined(__x86_64__)
__attribute__((target("avx2,fma"))) static float
dot_f32_avx2(const float *a, const float *b, size_t n)
{
    __m256 s0 = _mm256_setzero_ps(), s1 = _mm256_setzero_ps();
    size_t i = 0;
    for (; i + 16 <= n; i += 16) {
        s0 =
            _mm256_fmadd_ps(_mm256_loadu_ps(a + i), _mm256_loadu_ps(b + i), s0);
        s1 = _mm256_fmadd_ps(_mm256_loadu_ps(a + i + 8),
                             _mm256_loadu_ps(b + i + 8), s1);
    }
    for (; i + 8 <= n; i += 8)
        s0 =
            _mm256_fmadd_ps(_mm256_loadu_ps(a + i), _mm256_loadu_ps(b + i), s0);
    s0 = _mm256_add_ps(s0, s1);
    __m128 s =
        _mm_add_ps(_mm256_castps256_ps128(s0), _mm256_extractf128_ps(s0, 1));
    s = _mm_add_ps(s, _mm_movehl_ps(s, s));
    s = _mm_add_ss(s, _mm_movehdup_ps(s));
    float r = _mm_cvtss_f32(s);
    for (; i < n; i++)
        r += a[i] * b[i];
    return r;
}

__attribute__((target("avx2,fma"))) static void
axpy_f32_avx2(float *y, float a, const float *x, size_t n)
{
    __m256 va = _mm256_set1_ps(a);
    size_t i = 0;
    for (; i + 8 <= n; i += 8)
        _mm256_storeu_ps(y + i, _mm256_fmadd_ps(va, _mm256_loadu_ps(x + i),
                                                _mm256_loadu_ps(y + i)));
    for (; i < n; i++)
        y[i] += a * x[i];
}
#endif

#if defined(__aarch64__)
/* dot_f32_avx2 on NEON, step for step: each 8-lane register is two of four
   lanes (lo = lanes 0-3, hi = 4-7), the same 16- then 8-wide loops, s0 + s1
   lane for lane, janas_hsum8's pairing ((0+4)+(2+6)) + ((1+5)+(3+7)) by
   neon_sum8, and the unfused tail used by the current AVX2 path. */
static float dot_f32_neon(const float *a, const float *b, size_t n)
{
    float32x4_t s0l = vdupq_n_f32(0.0f), s0h = s0l, s1l = s0l, s1h = s0l;
    size_t i = 0;
    for (; i + 16 <= n; i += 16) {
        s0l = vfmaq_f32(s0l, vld1q_f32(a + i), vld1q_f32(b + i));
        s0h = vfmaq_f32(s0h, vld1q_f32(a + i + 4), vld1q_f32(b + i + 4));
        s1l = vfmaq_f32(s1l, vld1q_f32(a + i + 8), vld1q_f32(b + i + 8));
        s1h = vfmaq_f32(s1h, vld1q_f32(a + i + 12), vld1q_f32(b + i + 12));
    }
    for (; i + 8 <= n; i += 8) {
        s0l = vfmaq_f32(s0l, vld1q_f32(a + i), vld1q_f32(b + i));
        s0h = vfmaq_f32(s0h, vld1q_f32(a + i + 4), vld1q_f32(b + i + 4));
    }
    float r = neon_sum8(vaddq_f32(s0l, s1l), vaddq_f32(s0h, s1h));
    for (; i < n; i++)
        r += a[i] * b[i];
    return r;
}

/* Match AVX2's eight-element fused prefix and its unfused scalar tail. */
static void axpy_f32_neon(float *y, float a, const float *x, size_t n)
{
    float32x4_t va = vdupq_n_f32(a);
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        vst1q_f32(y + i, vfmaq_f32(vld1q_f32(y + i), va, vld1q_f32(x + i)));
        vst1q_f32(y + i + 4,
                  vfmaq_f32(vld1q_f32(y + i + 4), va, vld1q_f32(x + i + 4)));
    }
    for (; i < n; i++)
        y[i] += a * x[i];
}
#endif

/* Resolved before main, so the float helpers never race on it. */
__attribute__((constructor)) static void float_helpers_init(void)
{
#if defined(__x86_64__)
    __builtin_cpu_init();
    use_avx2_fma =
        __builtin_cpu_supports("avx2") && __builtin_cpu_supports("fma");
#endif
}

float janas_dot_f32(const float *a, const float *b, size_t n)
{
#if defined(__aarch64__)
    if (!janas_kernels_ref())
        return dot_f32_neon(a, b, n);
#endif
#if defined(__x86_64__)
    if (use_avx2_fma)
        return dot_f32_avx2(a, b, n);
#endif
    return dot_f32_ref(a, b, n);
}

void janas_axpy_f32(float *y, float a, const float *x, size_t n)
{
#if defined(__aarch64__)
    if (!janas_kernels_ref()) {
        axpy_f32_neon(y, a, x, n);
        return;
    }
#endif
#if defined(__x86_64__)
    if (use_avx2_fma) {
        axpy_f32_avx2(y, a, x, n);
        return;
    }
#endif
    axpy_f32_ref(y, a, x, n);
}

void janas_dot_rows(int type, const void *w, size_t row_bytes,
                    const struct janas_block_q8k *x, size_t nb, size_t rows,
                    float *y)
{
#if defined(__x86_64__)
    if (use_avx2_fma && __builtin_cpu_supports("f16c")) {
        typedef void (*rows_fn)(const void *, size_t,
                                const struct janas_block_q8k *, size_t, size_t,
                                float *);
        rows_fn f = NULL;
        switch (type) {
        case JANAS_Q4_K:
            f = KPICK(q4k_rows);
            break;
        case JANAS_Q6_K:
            f = KPICK(q6k_rows);
            break;
        case JANAS_Q5_K:
            f = KPICK(q5k_rows);
            break;
        case JANAS_Q8_0:
            f = KPICK(q8_0_rows);
            break;
        case JANAS_IQ4_NL:
            f = KPICK(iq4nl_rows);
            break;
        case JANAS_MXFP4:
            f = KPICK(mxfp4_rows);
            break;
        case JANAS_IQ4_XS:
            f = KPICK(iq4xs_rows);
            break;
        case JANAS_Q4_0:
            f = KPICK(q4_0_rows);
            break;
        case JANAS_Q5_1:
            f = KPICK(q5_1_rows);
            break;
        case JANAS_Q4_1:
            f = KPICK(q4_1_rows);
            break;
        case JANAS_Q5_0:
            f = KPICK(q5_0_rows);
            break;
        case JANAS_Q2_0:
            f = KPICK(q2_0_rows);
            break;
        case JANAS_Q3_K:
            f = KPICK(q3k_rows);
            break;
        case JANAS_Q2_K:
            f = KPICK(q2k_rows);
            break;
        case JANAS_IQ3_S:
            f = KPICK(iq3s_rows);
            break;
        case JANAS_IQ3_XXS:
            f = KPICK(iq3xxs_rows);
            break;
        case JANAS_IQ1_M:
            f = KPICK(iq1m_rows);
            break;
        case JANAS_IQ1_S:
            f = KPICK(iq1s_rows);
            break;
        }
        if (f) {
            f(w, row_bytes, x, nb, rows, y);
            return;
        }
    }
#endif
    for (size_t r = 0; r < rows; r++)
        y[r] = janas_dot(type, (const char *)w + r * row_bytes, x, nb);
}

void janas_dot_multi_rows(int type, const void *w, size_t row_bytes,
                          const struct janas_block_q8k *x, size_t x_stride,
                          size_t nv, size_t nb, size_t rows, float *y,
                          size_t y_stride)
{
#if defined(__x86_64__)
    if (type == JANAS_Q2_0 && use_avx2_fma && __builtin_cpu_supports("f16c")) {
        size_t r8 = use_tiles && nv >= TILES_MIN_NV_Q20 ? rows / 8 * 8 : 0;
        size_t r16 = use_z ? r8 / 16 * 16 : 0;
        if (r16)
            b32_gemm_z(type, w, row_bytes, x, x_stride, nv, nb, r16, y,
                       y_stride);
        if (r8 > r16)
            (KPICK(b32_gemm))(type, (const char *)w + r16 * row_bytes,
                              row_bytes, x, x_stride, nv, nb, r8 - r16, y + r16,
                              y_stride);
        if (rows > r8)
            (KPICK(q2_0_multi_rows))((const char *)w + r8 * row_bytes,
                                     row_bytes, x, x_stride, nv, nb, rows - r8,
                                     y + r8, y_stride);
        return;
    }
    if (use_tiles && use_avx2_fma && nv >= (size_t)TILES_MIN_NV_B32 &&
        rows >= 8 && __builtin_cpu_supports("f16c")) {
        size_t r8 = rows / 8 * 8, r16 = use_z ? r8 / 16 * 16 : 0;
        if (r16 && !b32_gemm_z(type, w, row_bytes, x, x_stride, nv, nb, r16, y,
                               y_stride))
            r16 = 0; /* not a type of theirs */
        if (r8 == r16 ||
            (KPICK(b32_gemm))(type, (const char *)w + r16 * row_bytes,
                              row_bytes, x, x_stride, nv, nb, r8 - r16, y + r16,
                              y_stride)) {
            w = (const char *)w + r8 * row_bytes;
            y += r8;
            rows -= r8;
            if (!rows)
                return;
        }
    }
    if (use_vnni && KPICK_VNNI(b32_multi_rows)(type, w, row_bytes, x, x_stride,
                                               nv, nb, rows, y, y_stride))
        return;
    if (type == JANAS_Q4_K && use_avx2_fma && __builtin_cpu_supports("f16c")) {
        size_t r8 = use_tiles && nv >= TILES_MIN_NV ? rows / 8 * 8 : 0;
        size_t r16 = use_z ? r8 / 16 * 16 : 0;
        if (r16)
            q4k_gemm_z(w, row_bytes, x, x_stride, nv, nb, r16, y, y_stride);
        if (r8 > r16)
            (KPICK(q4k_gemm))((const char *)w + r16 * row_bytes, row_bytes, x,
                              x_stride, nv, nb, r8 - r16, y + r16, y_stride);
        if (rows > r8)
            (KPICK(q4k_multi_rows))((const char *)w + r8 * row_bytes, row_bytes,
                                    x, x_stride, nv, nb, rows - r8, y + r8,
                                    y_stride);
        return;
    }
    if (type == JANAS_Q5_K && use_avx2_fma && __builtin_cpu_supports("f16c")) {
        size_t r8 = use_tiles && nv >= TILES_MIN_NV ? rows / 8 * 8 : 0;
        size_t r16 = use_z ? r8 / 16 * 16 : 0;
        if (r16)
            q5k_gemm_z(w, row_bytes, x, x_stride, nv, nb, r16, y, y_stride);
        if (r8 > r16)
            (KPICK(q5k_gemm))((const char *)w + r16 * row_bytes, row_bytes, x,
                              x_stride, nv, nb, r8 - r16, y + r16, y_stride);
        if (rows > r8)
            (KPICK(q5k_multi_rows))((const char *)w + r8 * row_bytes, row_bytes,
                                    x, x_stride, nv, nb, rows - r8, y + r8,
                                    y_stride);
        return;
    }
    if (type == JANAS_IQ4_XS && use_tiles && use_avx2_fma &&
        nv >= TILES_MIN_NV && rows >= 8 && __builtin_cpu_supports("f16c")) {
        size_t r8 = rows / 8 * 8, r16 = use_z ? r8 / 16 * 16 : 0;
        if (r16)
            iq4xs_gemm_z(w, row_bytes, x, x_stride, nv, nb, r16, y, y_stride);
        if (r8 > r16)
            (KPICK(iq4xs_gemm))((const char *)w + r16 * row_bytes, row_bytes, x,
                                x_stride, nv, nb, r8 - r16, y + r16, y_stride);
        w = (const char *)w + r8 * row_bytes;
        y += r8;
        rows -= r8;
    }
    if (use_tiles && use_avx2_fma && nv >= (size_t)TILES_MIN_NV_IQK &&
        rows >= 8 && __builtin_cpu_supports("f16c")) {
        size_t r8 = rows / 8 * 8, r16 = use_z ? r8 / 16 * 16 : 0;
        if (r16 && !iqk_gemm_z(type, w, row_bytes, x, x_stride, nv, nb, r16, y,
                               y_stride))
            r16 = 0; /* not a type of theirs */
        if (r8 == r16 ||
            (KPICK(iqk_gemm))(type, (const char *)w + r16 * row_bytes,
                              row_bytes, x, x_stride, nv, nb, r8 - r16, y + r16,
                              y_stride)) {
            w = (const char *)w + r8 * row_bytes;
            y += r8;
            rows -= r8;
        }
    }
    if (type == JANAS_Q6_K || type == JANAS_Q3_K) {
        size_t r8 = janas_q6k_tile_rows(type, w, row_bytes, NULL, NULL, 0, x,
                                        x_stride, nv, nb, rows, y, y_stride);
        w = (const char *)w + r8 * row_bytes;
        y += r8;
        rows -= r8;
    }
#endif
    for (size_t r = 0; r < rows; r++)
        janas_dot_multi(type, (const char *)w + r * row_bytes, x, x_stride, nv,
                        nb, y + r, y_stride);
}

void janas_dot_multi(int type, const void *w, const struct janas_block_q8k *x,
                     size_t x_stride, size_t nv, size_t nb, float *out,
                     size_t out_stride)
{
    size_t v = 0;
#if defined(__x86_64__)
    if (type == JANAS_NVFP4 && use_avx2_fma) {
        float r[8];
        for (; v < nv; v += 8) {
            int g = nv - v >= 8 ? 8 : (int)(nv - v);
            nvfp4_dotn_avx2(w, x + v * x_stride, x_stride, g, nb, r);
            for (int i = 0; i < g; i++)
                out[(v + (size_t)i) * out_stride] = r[i];
        }
        return;
    }
    if (use_avx2_fma && __builtin_cpu_supports("f16c") &&
        (type == JANAS_Q4_K || type == JANAS_Q6_K || type == JANAS_Q5_K ||
         type == JANAS_Q8_0 || type == JANAS_IQ4_NL || type == JANAS_IQ4_XS ||
         type == JANAS_Q4_0 || type == JANAS_Q5_1 || type == JANAS_Q4_1 ||
         type == JANAS_Q3_K || type == JANAS_IQ3_S || type == JANAS_MXFP4 ||
         type == JANAS_Q5_0 || type == JANAS_Q2_0 || type == JANAS_IQ3_XXS ||
         type == JANAS_IQ2_XXS || type == JANAS_IQ2_XS || type == JANAS_IQ2_S ||
         type == JANAS_IQ1_M || type == JANAS_IQ1_S || type == JANAS_Q2_K)) {
        float r[8];
        int g = 1;
        for (; v < nv; v += (size_t)g) {
            /* groups of 8, then the rest in one group */
            g = nv - v >= 8 ? 8 : (int)(nv - v);
            const struct janas_block_q8k *xv = x + v * x_stride;
            switch (type) {
            case JANAS_Q4_K:
                (KPICK(q4k_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q6_K:
                (KPICK(q6k_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q5_K:
                (KPICK(q5k_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ4_NL:
                (KPICK(iq4nl_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_MXFP4:
                (KPICK(mxfp4_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ4_XS:
                (KPICK(iq4xs_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q4_0:
                (KPICK(q4_0_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q5_1:
                (KPICK(q5_1_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q4_1:
                (KPICK(q4_1_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q5_0:
                (KPICK(q5_0_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q2_0:
                (KPICK(q2_0_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q3_K:
                (KPICK(q3k_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q2_K:
                (KPICK(q2k_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ3_S:
                (KPICK(iq3s_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ3_XXS:
                (KPICK(iq3xxs_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ2_XXS:
            case JANAS_IQ2_XS:
            case JANAS_IQ2_S:
                (KPICK(iq2_dotn))(type, w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ1_M:
                (KPICK(iq1m_dotn))(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_IQ1_S:
                (KPICK(iq1s_dotn))(w, xv, x_stride, g, nb, r);
                break;
            default:
                (KPICK(q8_0_dotn))(w, xv, x_stride, g, nb, r);
            }
            for (int i = 0; i < g; i++)
                out[(v + (size_t)i) * out_stride] = r[i];
        }
        return;
    }
#elif defined(__aarch64__)
    if (dot40_impl == q4_0_dot_neon &&
        (type == JANAS_Q4_0 || type == JANAS_IQ4_NL || type == JANAS_Q8_0 ||
         type == JANAS_Q6_K || type == JANAS_Q4_K || type == JANAS_Q5_K ||
         type == JANAS_Q3_K || type == JANAS_IQ3_S || type == JANAS_IQ4_XS ||
         type == JANAS_MXFP4 || type == JANAS_Q4_1 || type == JANAS_Q5_1)) {
        float r[8];
        int g = 1;
        for (; v < nv; v += (size_t)g) {
            g = nv - v >= 8 ? 8 : (int)(nv - v);
            const struct janas_block_q8k *xv = x + v * x_stride;
            switch (type) {
            case JANAS_Q4_0:
                neon_nib_dotn(w, xv, x_stride, g, nb, r, janas_q4_0_values);
                break;
            case JANAS_IQ4_NL:
                neon_nib_dotn(w, xv, x_stride, g, nb, r, janas_iq4_values);
                break;
            case JANAS_Q6_K:
                q6k_dotn_neon(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q4_K:
                neon_kmin_dotn(w, sizeof(struct janas_block_q4k), 0, xv,
                               x_stride, g, nb, r);
                break;
            case JANAS_Q5_K:
                neon_kmin_dotn(w, sizeof(struct janas_block_q5k), 1, xv,
                               x_stride, g, nb, r);
                break;
            case JANAS_Q3_K:
            case JANAS_IQ3_S:
            case JANAS_IQ4_XS:
                neon_kgroup_dotn(type, w, xv, x_stride, g, nb, r);
                break;
            case JANAS_MXFP4:
                mxfp4_dotn_neon(w, xv, x_stride, g, nb, r);
                break;
            case JANAS_Q4_1:
                neon_dm_dotn(w, sizeof(struct janas_block_q4_1), 0, xv,
                             x_stride, g, nb, r);
                break;
            case JANAS_Q5_1:
                neon_dm_dotn(w, sizeof(struct janas_block_q5_1), 1, xv,
                             x_stride, g, nb, r);
                break;
            default:
                q8_0_dotn_neon(w, xv, x_stride, g, nb, r);
            }
            for (int i = 0; i < g; i++)
                out[(v + (size_t)i) * out_stride] = r[i];
        }
        return;
    }
#endif
    for (; v < nv; v++)
        out[v * out_stride] = janas_dot(type, w, x + v * x_stride, nb);
}

size_t janas_qtype_row_bytes(int type, size_t n)
{
    size_t sub, bytes; /* the types in blocks of 32 or 64 weights */
    switch (type) {
    case JANAS_Q8_0:
        sub = 32, bytes = sizeof(struct janas_block_q8_0);
        break;
    case JANAS_IQ4_NL:
        sub = 32, bytes = sizeof(struct janas_block_iq4nl);
        break;
    case JANAS_MXFP4:
        sub = 32, bytes = sizeof(struct janas_block_mxfp4);
        break;
    case JANAS_NVFP4:
        sub = 64, bytes = sizeof(struct janas_block_nvfp4);
        break;
    case JANAS_Q4_0:
        sub = 32, bytes = sizeof(struct janas_block_q4_0);
        break;
    case JANAS_Q5_1:
        sub = 32, bytes = sizeof(struct janas_block_q5_1);
        break;
    case JANAS_Q4_1:
        sub = 32, bytes = sizeof(struct janas_block_q4_1);
        break;
    case JANAS_Q5_0:
        sub = 32, bytes = sizeof(struct janas_block_q5_0);
        break;
    case JANAS_Q2_0:
        sub = 64, bytes = sizeof(struct janas_block_q2_0);
        break;
    default:
        sub = JANAS_QK, bytes = janas_qtype_block_size(type);
    }
    return n % sub == 0 ? n / sub * bytes : 0;
}

/* The largest group of a type in blocks of 32 or 64: Q8_0's. */
#define TAIL_GROUP (8 * sizeof(struct janas_block_q8_0))

/* The tail of a row, its bytes past `full`, into pad padded with zero
   blocks to a whole group. */
static void tail_group(int type, const void *row, size_t full, size_t row_bytes,
                       uint8_t *pad)
{
    /* a shape the type cannot end inside a group with (row_bytes 0, or
       not past the whole groups): the loaders refuse it; a pad of zeros
       here rather than a copy past the row */
    size_t bs = janas_qtype_block_size(type);
    if (row_bytes <= full || row_bytes - full > bs || bs > TAIL_GROUP) {
        memset(pad, 0, TAIL_GROUP);
        return;
    }
    size_t tb = row_bytes - full;
    memcpy(pad, (const uint8_t *)row + full, tb);
    memset(pad + tb, 0, janas_qtype_block_size(type) - tb);
}

float janas_dot_n(int type, const void *w, const struct janas_block_q8k *x,
                  size_t n)
{
    size_t nb = n / JANAS_QK;
    if (n % JANAS_QK == 0)
        return janas_dot(type, w, x, nb);
    _Alignas(64) uint8_t pad[TAIL_GROUP];
    tail_group(type, w, nb * janas_qtype_block_size(type),
               janas_qtype_row_bytes(type, n), pad);
    float s = nb ? janas_dot(type, w, x, nb) : 0.0f;
    return s + janas_dot(type, pad, x + nb, 1);
}

void janas_dot_rows_n(int type, const void *w, size_t row_bytes,
                      const struct janas_block_q8k *x, size_t n, size_t rows,
                      float *y)
{
    size_t nb = n / JANAS_QK;
    if (n % JANAS_QK == 0) {
        janas_dot_rows(type, w, row_bytes, x, nb, rows, y);
        return;
    }
    /* the whole groups row by row, then the tails a few rows at a time */
    enum { CHUNK = 32 };
    size_t gb = janas_qtype_block_size(type), full = nb * gb;
    _Alignas(64) uint8_t pad[CHUNK * TAIL_GROUP];
    float t[CHUNK];
    if (nb)
        janas_dot_rows(type, w, row_bytes, x, nb, rows, y);
    for (size_t r0 = 0; r0 < rows; r0 += CHUNK) {
        size_t c = rows - r0 < CHUNK ? rows - r0 : CHUNK;
        for (size_t i = 0; i < c; i++)
            tail_group(type, (const uint8_t *)w + (r0 + i) * row_bytes, full,
                       row_bytes, pad + i * gb);
        janas_dot_rows(type, pad, gb, x + nb, 1, c, t);
        for (size_t i = 0; i < c; i++)
            y[r0 + i] = (nb ? y[r0 + i] : 0.0f) + t[i];
    }
}

/* the whole groups of all the rows, then the tails CHUNK rows and VEC
   vectors at a time: janas_dot_multi_rows gives them the tiles */
void janas_dot_multi_rows_n(int type, const void *w, size_t row_bytes,
                            const struct janas_block_q8k *x, size_t x_stride,
                            size_t nv, size_t n, size_t rows, float *y,
                            size_t y_stride)
{
    size_t nb = n / JANAS_QK;
    if (n % JANAS_QK == 0) {
        janas_dot_multi_rows(type, w, row_bytes, x, x_stride, nv, nb, rows, y,
                             y_stride);
        return;
    }
    enum { CHUNK = 16, VEC = 64 };
    size_t gb = janas_qtype_block_size(type), full = nb * gb;
    _Alignas(64) uint8_t pad[CHUNK * TAIL_GROUP];
    float t[CHUNK * VEC];
    if (nb)
        janas_dot_multi_rows(type, w, row_bytes, x, x_stride, nv, nb, rows, y,
                             y_stride);
    for (size_t r0 = 0; r0 < rows; r0 += CHUNK) {
        size_t c = rows - r0 < CHUNK ? rows - r0 : CHUNK;
        for (size_t i = 0; i < c; i++)
            tail_group(type, (const uint8_t *)w + (r0 + i) * row_bytes, full,
                       row_bytes, pad + i * gb);
        for (size_t v0 = 0; v0 < nv; v0 += VEC) {
            size_t g = nv - v0 < VEC ? nv - v0 : VEC;
            janas_dot_multi_rows(type, pad, gb, x + v0 * x_stride + nb,
                                 x_stride, g, 1, c, t, c);
            for (size_t v = 0; v < g; v++)
                for (size_t i = 0; i < c; i++) {
                    float *o = y + r0 + i + (v0 + v) * y_stride;
                    *o = (nb ? *o : 0.0f) + t[i + v * c];
                }
        }
    }
}

void janas_dot_multi_n(int type, const void *w, const struct janas_block_q8k *x,
                       size_t x_stride, size_t nv, size_t n, float *out,
                       size_t out_stride)
{
    size_t nb = n / JANAS_QK;
    if (n % JANAS_QK == 0) {
        janas_dot_multi(type, w, x, x_stride, nv, nb, out, out_stride);
        return;
    }
    _Alignas(64) uint8_t pad[TAIL_GROUP];
    tail_group(type, w, nb * janas_qtype_block_size(type),
               janas_qtype_row_bytes(type, n), pad);
    if (nb)
        janas_dot_multi(type, w, x, x_stride, nv, nb, out, out_stride);
    float t[8];
    for (size_t v = 0; v < nv; v += 8) {
        size_t g = nv - v < 8 ? nv - v : 8;
        janas_dot_multi(type, pad, x + v * x_stride + nb, x_stride, g, 1, t, 1);
        for (size_t i = 0; i < g; i++) {
            float *o = out + (v + i) * out_stride;
            *o = (nb ? *o : 0.0f) + t[i];
        }
    }
}
